WITH sales_with_time AS (SELECT cc.cc_name, cs.cs_sold_time_sk, td.t_hour, cs.cs_net_profit, cs.cs_ext_discount_amt, CASE WHEN cs.cs_ext_discount_amt >= 1000 THEN 'High Discount' WHEN cs.cs_ext_discount_amt >= 500 THEN 'Medium Discount' ELSE 'Low Discount' END AS discount_category, ship_c.c_customer_id AS ship_customer_id FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN time_dim td ON cs.cs_sold_time_sk = td.t_time_sk JOIN customer ship_c ON cs.cs_ship_customer_sk = ship_c.c_customer_sk) SELECT cc_name, cs_sold_time_sk, t_hour, discount_category, ship_customer_id, cs_net_profit, SUM(cs_net_profit) OVER (PARTITION BY cc_name ORDER BY cs_sold_time_sk ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_profit, RANK() OVER (PARTITION BY cc_name ORDER BY cs_net_profit DESC) AS profit_rank_per_sale FROM sales_with_time ORDER BY cc_name, cs_sold_time_sk
